PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX oio: <http://www.geneontology.org/formats/oboInOwl#>
PREFIX obo: <http://purl.obolibrary.org/obo/>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?p ?o WHERE {
  VALUES ?s { <http://purl.obolibrary.org/obo/UBERON_0010409> }
  VALUES ?p { skos:exactMatch skos:closeMatch skos:broadMatch skos:narrowMatch
              skos:relatedMatch owl:equivalentClass }
  GRAPH <http://reasoner.renci.org/ontology> { ?s ?p ?o . FILTER(isIRI(?o)) }
}
